class Participante {
  constructor(nombre, votaSi = true) { this.nombre = nombre; this.votaSi = votaSi; this.estado = 'libre'; }
  preparar() {
    if (!this.votaSi) { this.estado = 'abortado'; return 'NO'; }
    this.estado = 'preparado';          // desde acá retiene sus bloqueos y ya no puede abortar solo
    return 'SI';
  }
  decidir(d) { this.estado = d === 'COMMIT' ? 'confirmado' : 'abortado'; }
}

function correr(titulo, { vota = [true, true, true], cae = null } = {}) {
  const ps = ['stock', 'pagos', 'transporte'].map((n, i) => new Participante(n, vota[i]));
  const log = [];                        // el log durable del coordinador
  console.log('--- ' + titulo);
  const votos = ps.map(p => p.preparar());
  console.log('fase 1, votos:', ps.map((p, i) => p.nombre + '=' + votos[i]).join(' '));
  const decision = votos.every(v => v === 'SI') ? 'COMMIT' : 'ROLLBACK';
  if (cae === 'antes') {
    console.log('el coordinador se cae ANTES de anotar la decisión');
  } else {
    log.push(decision);                  // anotar ANTES de avisar
    if (cae === 'despues') {
      console.log('el coordinador anota ' + decision + ' y se cae antes de avisar');
    } else {
      ps.forEach(p => p.decidir(decision));
    }
  }
  if (cae) {
    console.log('  mientras está caído, sea 1 minuto o 2 horas:', ps.map(p => p.nombre + ':' + p.estado).join(' '));
    const d = log[0] ?? 'ROLLBACK';     // regla de recuperación: sin decisión anotada, se aborta
    console.log('el coordinador vuelve, lee su log (' + (log[0] ?? 'vacío') + ') y manda ' + d);
    ps.forEach(p => p.decidir(d));
  }
  console.log('final:', ps.map(p => p.nombre + ':' + p.estado).join(' '));
}

correr('A. todos votan que sí');
correr('B. transporte vota que no', { vota: [true, true, false] });
correr('C. se cae antes de decidir', { cae: 'antes' });
correr('D. se cae después de anotar', { cae: 'despues' });

// Saga orquestada: un orquestador ejecuta pasos y, si uno falla, compensa en orden inverso.
const mundo = { stockLibre: 5, reservas: 0, cobrado: 0, saldoCliente: 900000, camionesLibres: 0, log: [] };
const anotar = (m) => { mundo.log.push(m); console.log(m); };

const pasos = [
  { nombre: 'reservar stock',
    hacer: () => { mundo.stockLibre--; mundo.reservas++; },
    compensar: () => { mundo.stockLibre++; mundo.reservas--; } },
  { nombre: 'cobrar',
    hacer: () => { mundo.saldoCliente -= 450000; mundo.cobrado += 450000; },
    compensar: () => { mundo.saldoCliente += 450000; mundo.cobrado -= 450000; } },
  { nombre: 'asignar transporte',
    hacer: () => { if (mundo.camionesLibres < 1) throw new Error('sin camiones'); mundo.camionesLibres--; },
    compensar: () => { mundo.camionesLibres++; } },
];

function estado() { return `stock=${mundo.stockLibre} reservas=${mundo.reservas} cobrado=${mundo.cobrado} saldo=${mundo.saldoCliente}`; }

function correrSaga() {
  const hechos = [];
  for (const p of pasos) {
    try {
      p.hacer(); hechos.push(p);
      anotar('OK     ' + p.nombre.padEnd(20) + estado());
    } catch (e) {
      anotar('FALLÓ  ' + p.nombre.padEnd(20) + '(' + e.message + ')');
      for (const q of hechos.reverse()) {
        q.compensar();
        anotar('COMPENSA ' + q.nombre.padEnd(18) + estado());
      }
      return 'abortada';
    }
  }
  return 'completa';
}
console.log('resultado:', correrSaga());

// Compensación que falla y se reintenta, sobre un libro de movimientos (no se borra nada).
const libro = [];
let fallosDelReembolso = 2;                       // el servicio de pagos falla las dos primeras veces
const saldo = () => libro.reduce((s, m) => s + m.monto, 900000);

function cobrar(pedido) { libro.push({ id: 'cobro:' + pedido, monto: -450000 }); }
function reembolsar(pedido) {
  if (libro.some(m => m.id === 'reembolso:' + pedido)) return 'ya estaba';   // idempotente: una sola vez
  if (fallosDelReembolso-- > 0) throw new Error('pagos no responde');
  libro.push({ id: 'reembolso:' + pedido, monto: +450000 });
  return 'hecho';
}

cobrar('77');
console.log('el cliente ve su saldo:', saldo());
for (let intento = 1; intento <= 5; intento++) {
  try { console.log('reembolso, intento ' + intento + ':', reembolsar('77')); } catch (e) { console.log('reembolso, intento ' + intento + ': error (' + e.message + ')'); continue; }
  break;
}
console.log('un reintento de más:', reembolsar('77'));
console.log('saldo final:', saldo(), '| movimientos:', libro.map(m => m.id + ' ' + m.monto).join(', '));
